CREATE TABLE public.policiais (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  re text NOT NULL UNIQUE,
  nome text NOT NULL,
  posto text NOT NULL DEFAULT '',
  ordem integer NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
GRANT SELECT, INSERT, UPDATE, DELETE ON public.policiais TO authenticated;
GRANT ALL ON public.policiais TO service_role;
ALTER TABLE public.policiais ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Aprovados veem efetivo" ON public.policiais FOR SELECT TO authenticated USING (public.is_approved(auth.uid()));
CREATE POLICY "Aprovados inserem efetivo" ON public.policiais FOR INSERT TO authenticated WITH CHECK (public.is_approved(auth.uid()));
CREATE POLICY "Aprovados atualizam efetivo" ON public.policiais FOR UPDATE TO authenticated USING (public.is_approved(auth.uid())) WITH CHECK (public.is_approved(auth.uid()));
CREATE POLICY "Aprovados removem efetivo" ON public.policiais FOR DELETE TO authenticated USING (public.is_approved(auth.uid()));
CREATE TRIGGER policiais_updated_at BEFORE UPDATE ON public.policiais FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();

CREATE TABLE public.materiais (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  nome text NOT NULL UNIQUE,
  ordem integer NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
GRANT SELECT, INSERT, UPDATE, DELETE ON public.materiais TO authenticated;
GRANT ALL ON public.materiais TO service_role;
ALTER TABLE public.materiais ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Aprovados veem materiais" ON public.materiais FOR SELECT TO authenticated USING (public.is_approved(auth.uid()));
CREATE POLICY "Aprovados inserem materiais" ON public.materiais FOR INSERT TO authenticated WITH CHECK (public.is_approved(auth.uid()));
CREATE POLICY "Aprovados atualizam materiais" ON public.materiais FOR UPDATE TO authenticated USING (public.is_approved(auth.uid())) WITH CHECK (public.is_approved(auth.uid()));
CREATE POLICY "Aprovados removem materiais" ON public.materiais FOR DELETE TO authenticated USING (public.is_approved(auth.uid()));
CREATE TRIGGER materiais_updated_at BEFORE UPDATE ON public.materiais FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();

INSERT INTO public.materiais (nome, ordem) VALUES ('Fardamento',0),('Bota',1),('Boina',2),('Cinturão',3),('Coldre',4),('Japona',5),('Fiel',6),('Adicional 1',7),('Adicional 2',8) ON CONFLICT (nome) DO NOTHING;

